// Embedded high-resolution optimized base64 data for store logos in PDF invoices
export const SANGAM_SALES_LOGO_BASE64 = 'data:image/png;base64,';

export const SANGAM_TRADERS_LOGO_BASE64 = 'data:image/png;base64,';

export function getStoreLogoBase64(logoUrl?: string, shopName?: string): string {
  if (logoUrl?.startsWith('data:image/')) {
    return logoUrl;
  }
  if (
    logoUrl?.toLowerCase().includes('trader') ||
    shopName?.toLowerCase().includes('trader')
  ) {
    return SANGAM_TRADERS_LOGO_BASE64;
  }
  return SANGAM_SALES_LOGO_BASE64;
}
